package org.icu.sepsis.deterioration;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import java.time.*;import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.icu.sepsis.application.Store;import org.icu.sepsis.domain.Domain.*;import org.icu.sepsis.integration.ClinicalDataProvider;import org.icu.sepsis.api.ApiException;
import org.springframework.data.mongodb.core.MongoTemplate;import org.springframework.data.mongodb.core.query.Query;import org.junit.jupiter.api.*;
class ReviewedLabEvidenceServiceTest {
 final Instant now=Instant.parse("2026-11-19T08:00:00Z");final MongoTemplate db=mock(MongoTemplate.class);final ClinicalDataProvider source=mock(ClinicalDataProvider.class);
 final Store store=new Store(db,"ICU",new ObjectMapper().registerModule(new JavaTimeModule()));final ReviewedLabEvidenceService service=new ReviewedLabEvidenceService(store,source);
 final Patient p=new Patient();final Observation lab=new Observation();
 @BeforeEach void setup(){when(db.findAndModify(any(Query.class),any(org.springframework.data.mongodb.core.query.Update.class),any(org.springframework.data.mongodb.core.FindAndModifyOptions.class),eq(ReviewedLabEvidenceService.Sequence.class))).thenAnswer(inv->{var head=new ReviewedLabEvidenceService.Sequence();head.sequence=1;return head;});p.id="synthetic-p";p.encounterId="stay";p.department="ICU";p.admittedAt=now.minus(Duration.ofDays(10));lab.patientId=p.id;lab.encounterId=p.encounterId;lab.department=p.department;lab.parameterCode="CREA";lab.sourceRecordId="synthetic-report";lab.sourceSystem="synthetic-lab";lab.value=120d;lab.unit="μmol/L";lab.eventTime=now.minusSeconds(3600);lab.clinicalUse="context_only";lab.qualityStatus="unverified";lab.encounterLinkStatus="unconfirmed";when(source.observations(anyString(),anyString(),any(),any())).thenReturn(List.of(lab));when(db.find(any(Query.class),eq(ReviewedLabEvidenceService.Review.class))).thenReturn(List.of());}
 ReviewedLabEvidenceService.Request request(){var r=new ReviewedLabEvidenceService.Request();r.encounterId=p.encounterId;r.sourceRecordId=lab.sourceRecordId;r.parameterCode="CREA";r.fingerprint=service.fingerprint(lab);r.accepted=true;r.observedAt=now.minusSeconds(4000);r.reason="合成测试：已核对住院与采样时间";return r;}
 @Test void confirmedSourceAppliesOnlyToSeparateCopyAndCanBeWithdrawn(){var r=service.record(p,request(),"doctor",now);verify(db).insert(r);when(db.find(any(Query.class),eq(ReviewedLabEvidenceService.Review.class))).thenReturn(List.of(r));var reviewed=service.apply(p,List.of(lab),now).get(0);assertEquals("physician_confirmed",reviewed.encounterLinkStatus);assertEquals("valid",reviewed.qualityStatus);assertEquals(now,reviewed.ingestTime);assertEquals("unverified",lab.qualityStatus);assertEquals("context_only",lab.clinicalUse);r.accepted=false;assertSame(lab,service.apply(p,List.of(lab),now).get(0));}
 @Test void changedSourceOrStayCannotReuseConfirmation(){var r=service.record(p,request(),"doctor",now);when(db.find(any(Query.class),eq(ReviewedLabEvidenceService.Review.class))).thenReturn(List.of(r));lab.value=160d;assertSame(lab,service.apply(p,List.of(lab),now).get(0));var req=request();req.encounterId="old-stay";assertThrows(ApiException.class,()->service.record(p,req,"doctor",now));}
 @Test void futureAndPriorAdmissionTimesAndStaleFingerprintsAreRejected(){var req=request();req.observedAt=now.plusSeconds(1);assertThrows(ApiException.class,()->service.record(p,req,"doctor",now));req.observedAt=p.admittedAt.minusSeconds(1);assertThrows(ApiException.class,()->service.record(p,req,"doctor",now));req.observedAt=now.minusSeconds(1);req.fingerprint="stale";assertThrows(ApiException.class,()->service.record(p,req,"doctor",now));verify(db,never()).insert(any(ReviewedLabEvidenceService.Review.class));}
 @Test void crossStayOrAmbiguousSourceCannotBeConfirmed(){var req=request();lab.encounterId="other";assertThrows(ApiException.class,()->service.record(p,req,"doctor",now));lab.encounterId=p.encounterId;when(source.observations(anyString(),anyString(),any(),any())).thenReturn(List.of(lab,lab));assertThrows(ApiException.class,()->service.record(p,req,"doctor",now));}
 @Test void pendingEvidenceKeepsReportedTimeSeparateFromObservedTime(){var pending=service.pending(p,List.of(lab),now).get(0);assertEquals(lab.eventTime,pending.get("reportedAt"));assertNull(pending.get("observedAt"));assertEquals(false,pending.get("reviewed"));}

 @Test void staleReviewVersionCannotOverwriteAConfirmation(){var previous=service.record(p,request(),"doctor",now);when(db.find(any(Query.class),eq(ReviewedLabEvidenceService.Review.class))).thenReturn(List.of(previous));assertThrows(ApiException.class,()->service.record(p,request(),"other-doctor",now));verify(db,times(1)).insert(any(ReviewedLabEvidenceService.Review.class));}
 @Test void racingHeadUpdateIsReportedAsAConflict(){when(db.findAndModify(any(Query.class),any(org.springframework.data.mongodb.core.query.Update.class),any(org.springframework.data.mongodb.core.FindAndModifyOptions.class),eq(ReviewedLabEvidenceService.Sequence.class))).thenThrow(new org.springframework.dao.DuplicateKeyException("synthetic collision"));assertThrows(ApiException.class,()->service.record(p,request(),"doctor",now));verify(db,never()).insert(any(ReviewedLabEvidenceService.Review.class));}
 @Test void failedRecordInsertRollsBackOnlyItsOwnReservedHead(){doThrow(new IllegalStateException("synthetic write failure")).when(db).insert(any(ReviewedLabEvidenceService.Review.class));assertThrows(IllegalStateException.class,()->service.record(p,request(),"doctor",now));verify(db).updateFirst(any(Query.class),any(org.springframework.data.mongodb.core.query.Update.class),eq(ReviewedLabEvidenceService.Sequence.class));}

 @Test void displayAndCalculationUseTheSameReviewSnapshotEvenWhenAnotherDoctorRevokes(){var confirmed=service.record(p,request(),"doctor",now);var withdrawn=new ReviewedLabEvidenceService.Review();org.springframework.beans.BeanUtils.copyProperties(confirmed,withdrawn);withdrawn.accepted=false;clearInvocations(db);when(db.find(any(Query.class),eq(ReviewedLabEvidenceService.Review.class))).thenReturn(List.of(confirmed),List.of(withdrawn));var first=service.resolve(p,List.of(lab),now);assertEquals(true,first.evidence.get(0).get("reviewed"));assertEquals("valid",first.observations.get(0).qualityStatus);verify(db,times(1)).find(any(Query.class),eq(ReviewedLabEvidenceService.Review.class));var next=service.resolve(p,List.of(lab),now);assertEquals(false,next.evidence.get(0).get("reviewed"));assertEquals("unverified",next.observations.get(0).qualityStatus);}
 @Test void missingObservationTimeCannotBeDisplayedAsAnActiveConfirmation(){var confirmed=service.record(p,request(),"doctor",now);confirmed.observedAt=null;when(db.find(any(Query.class),eq(ReviewedLabEvidenceService.Review.class))).thenReturn(List.of(confirmed));var result=service.resolve(p,List.of(lab),now);assertEquals(false,result.evidence.get(0).get("reviewed"));assertEquals("context_unavailable",result.evidence.get(0).get("reviewState"));assertSame(lab,result.observations.get(0));}
}
